import React, { useContext, useState } from 'react';
import { UserContext } from '../context/UserContext';
import axios from 'axios';

const UserForm = () => {
    const { addUser, validationPatterns } = useContext(UserContext);
    const [user, setUser] = useState({
        usuario: '',
        contra: '',
        nombre: '',
        apellidos: '',
        fecha_nacimiento: ''
    });
    const [error, setError] = useState('');

    // Maneja los cambios de los campos del formulario
    const handleChange = (e) => {
        const { name, value } = e.target;
        setUser((prevUser) => ({ ...prevUser, [name]: value }));
    };

    // Valida el nombre de usuario
    const validateusuario = (usuario) => validationPatterns.usuario.test(usuario);

    // Valida la contraseña
    const validatecontra = (contra) => validationPatterns.contra.test(contra);

    // Valida si el usuario es mayor de 18 años
    const validateAge = (fecha_nacimiento) => {
        const today = new Date();
        const birth = new Date(fecha_nacimiento);
        const age = today.getFullYear() - birth.getFullYear();
        const monthDiff = today.getMonth() - birth.getMonth();
        return age > 18 || (age === 18 && monthDiff >= 0);
    };

    // Maneja el envío del formulario
    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');  // Limpia errores previos

        // Validación de los campos antes de enviar
        if (!validateusuario(user.usuario)) {
            setError('El nombre de usuario debe tener al menos 6 caracteres, comenzar por una letra minuscula y no contener caracteres especiales.');
            return;
        }

        if (!validatecontra(user.contra)) {
            setError('La contraseña debe tener al menos 8 caracteres, contener al menos una letra mayúscula y un número.');
            return;
        }

        if (!validateAge(user.fecha_nacimiento)) {
            setError('Debes ser mayor de edad (18 años o más).');
            return;
        }

        try {
            // Enviar los datos del usuario al servidor
            const response = await axios.post('http://localhost/SERVIDOR/practica/api.php', user);
            addUser(response.data);  // Agregar el usuario a contexto
            setUser({ usuario: '', contra: '', nombre: '', apellidos: '', fecha_nacimiento: '' });  // Limpiar el formulario
        } catch (error) {
            console.error('Error al agregar el usuario:', error);
        }
    };

    return (
        <form onSubmit={handleSubmit}>
            {/* Mostrar el mensaje de error si existe */}
            {error && <p style={{ color: 'red' }}>{error}</p>}
            <input 
                type="text" 
                name="usuario"  // Asegúrate de que el nombre coincida con el backend
                placeholder="Nombre de usuario" 
                onChange={handleChange} 
                value={user.usuario} 
                required 
            />
            <input 
                type="password" 
                name="contra"  // Asegúrate de que el nombre coincida con el backend
                placeholder="Contraseña" 
                onChange={handleChange} 
                value={user.contra} 
                required 
            />
            <input 
                type="text" 
                name="nombre"  // Asegúrate de que el nombre coincida con el backend
                placeholder="Nombre" 
                onChange={handleChange} 
                value={user.nombre} 
                required 
            />
            <input 
                type="text" 
                name="apellidos"  // Asegúrate de que el nombre coincida con el backend
                placeholder="Apellidos" 
                onChange={handleChange} 
                value={user.apellidos} 
                required 
            />
            <input 
                type="date" 
                name="fecha_nacimiento"  // Asegúrate de que el nombre coincida con el backend
                onChange={handleChange} 
                value={user.fecha_nacimiento} 
                required 
            />
            <button type="submit">Agregar Usuario</button>
        </form>
    );
};

export default UserForm;
